ode[draw,circle] (a) at (0,0) {1}; 
ode[draw,circle] (b) at (2,0) {2}; 
ode[draw,circle] (c) at (1,1.5) {3}; 
ode[draw,circle] (d) at (3,1.5) {4}; \draw (a) -- (b) -- (c) -- (a); \draw[->] (b) -- (d); \draw[->] (c) to[bend left] (d);

ode[draw, rounded corners] (s) at (0,0) {Start}; 
ode[draw] (p) at (0,-1.2) {Read $n$}; 
ode[draw, circle] (q) at (0,-2.4) {$n>0$?}; 
ode[draw, rounded corners] (e) at (2.5,-2.4) {Stop}; \draw[->] (s) -- (p); \draw[->] (p) -- (q); \draw[->] (q) -- (e) node[midway, above] {no};

\coordinate (A) at (0,0); \coordinate (B) at (3,0); \coordinate (C) at (1,2); \draw (A) -- (B) -- (C) -- cycle; 
ode[below left] at (A) {$A$}; 
ode[below right] at (B) {$B$}; 
ode[above] at (C) {$C$}; 
ode[below] at ($(A)!0.5!(B)$) {$c$};

\draw (0,0) circle (1); \draw (1.2,0) circle (1); 
ode at (-0.4,0) {$A$}; 
ode at (1.6,0) {$B$}; 
ode at (0.6,0) {$A\cap B$}; 
ode[font=\small] at (0.6,-1.4) {two sets};

ode[draw, circle, label=above:$v_1$] (a) at (0,0) {}; 
ode[draw, circle, label=below:$v_2$] (b) at (2,0) {}; 
ode[draw, circle, label=right:$v_3$] (c) at (1,1.5) {}; \draw (a) -- (b) -- (c) -- (a);

\draw[gray] (-1.2,0) -- (1.2,0);
\draw[thick, domain=-1:1, samples=21] plot (\x, \x^2);
\draw[red, variable=\t, domain=0:1, samples=11] (0,-1) -- plot (\t, {1-(\t)^2});

\draw plot coordinates {(0,0) (1,1) (2,0.5) (3,1.5)};
\draw[smooth, green!60!black] plot coordinates {(0,-1) (1,0) (2,-0.5) (3,0.5)};
\draw[smooth, tension=1, blue] plot coordinates {(0,-2) (1,-1) (2,-1.5) (3,-0.5)};
